import{_ as a,o,c as r,a2 as t}from"./chunks/framework.BDCokyix.js";const u=JSON.parse('{"title":"SBOM","description":"","frontmatter":{},"headers":[],"relativePath":"security/sbom.md","filePath":"security/sbom.md","lastUpdated":1780254295000}'),s={name:"security/sbom.md"};function n(i,e,d,l,c,h){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="sbom" tabindex="-1">SBOM <a class="header-anchor" href="#sbom" aria-label="Permalink to &quot;SBOM&quot;">​</a></h1><p>Soma generates Software Bills of Materials (SBOMs) in CI to improve supply-chain visibility for desktop artifacts, backend binaries, and container images.</p><h2 id="what-is-generated" tabindex="-1">What is generated <a class="header-anchor" href="#what-is-generated" aria-label="Permalink to &quot;What is generated&quot;">​</a></h2><ul><li>Output format: <strong>SPDX JSON</strong> (<code>*.spdx.json</code>).</li><li>Generator: <strong>Syft</strong> via <code>anchore/sbom-action</code>.</li></ul><h2 id="where-sboms-are-produced" tabindex="-1">Where SBOMs are produced <a class="header-anchor" href="#where-sboms-are-produced" aria-label="Permalink to &quot;Where SBOMs are produced&quot;">​</a></h2><p>SBOMs are generated as part of the release and build workflows in <code>.github/workflows/</code>:</p><ul><li><code>release-server.yml</code>: produces <code>sbom-image-&lt;name&gt;.spdx.json</code> for the built <code>somad</code> backend image (and uploads it as an artifact).</li><li><code>release-desktop.yml</code>: produces the Tauri desktop release assets for Soma (no SBOM step yet).</li></ul><p>(The former per-service <code>release-daemons.yml</code>, the <code>release.yml</code> bundle workflow, and the <code>docker-backend.yml</code> image workflow were removed/renamed during the server-binary and Tauri collapses — see <code>AGENTS.md</code>.)</p><h2 id="how-to-consume" tabindex="-1">How to consume <a class="header-anchor" href="#how-to-consume" aria-label="Permalink to &quot;How to consume&quot;">​</a></h2><p>Recommended review practices:</p><ul><li>Treat SBOMs as <strong>inputs</strong> to vulnerability scanning and dependency review, not as proof of safety.</li><li>When investigating a CVE, use the SBOM to confirm whether a vulnerable component is present and at what version.</li><li>Prefer diffing SBOMs between releases to identify unexpected dependency changes.</li></ul><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>SBOMs are generated in CI; the repo does not maintain a checked-in <code>sbom/</code> scripts directory.</li><li>If you add new release artifacts (new binaries/images), ensure the workflow uploads an SBOM for them as well.</li></ul>',13)])])}const p=a(s,[["render",n]]);export{u as __pageData,p as default};
